CREATE TABLE memory_turns(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,conversation_id VARCHAR(80) NOT NULL,role VARCHAR(20) NOT NULL,content TEXT NOT NULL,media_type VARCHAR(80),created_at TIMESTAMP WITH TIME ZONE NOT NULL,expires_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE INDEX idx_memory_conversation ON memory_turns(conversation_id,created_at);
CREATE INDEX idx_memory_expiry ON memory_turns(expires_at);
